-- Attendance import generated from attendence.txt (1,365 source rows).
-- Includes combined location strings, numeric coordinates, addresses, and valid sync timestamps.
-- Does NOT delete or truncate any existing data.
-- Safety checks stop the import if attendance is not empty or any student_id is missing.
BEGIN;
CREATE TEMP TABLE attendance_import_stage (
    attendance_date text NOT NULL,
    student_id text NOT NULL,
    student_name text,
    check_in_time text,
    check_out_time text,
    status text,
    check_in_location text,
    check_in_latitude text,
    check_in_longitude text,
    check_in_address text,
    check_out_location text,
    check_out_latitude text,
    check_out_longitude text,
    check_out_address text,
    sync_timestamp text
) ON COMMIT DROP;


DO $$
DECLARE missing_ids text;
BEGIN
    IF EXISTS (SELECT 1 FROM public.attendance) THEN
        RAISE EXCEPTION 'Import stopped: public.attendance is not empty. No attendance rows were inserted. Verify the table before proceeding.';
    END IF;
    SELECT string_agg(x.student_id, ' , ') INTO missing_ids
    FROM (
        SELECT DISTINCT s.student_id
        FROM attendance_import_stage s
        LEFT JOIN public.student st ON st.student_id::text = s.student_id
        WHERE st.student_id IS NULL
        ORDER BY s.student_id
        LIMIT 20
    ) x;
    IF missing_ids IS NOT NULL THEN
        RAISE EXCEPTION 'Import stopped: these Student IDs do not exist in public.student (up to 20 shown): %', missing_ids;
    END IF;
END $$;

    student_id, date, check_in_time, check_out_time, check_in_location, check_out_location, status, created_at,
    check_in_address, check_out_address, check_in_latitude, check_in_longitude, check_out_latitude, check_out_longitude
)
SELECT
    student_id,
    attendance_date::date,
    NULLIF(check_in_time, '')::time,
    NULLIF(check_out_time, '')::time,
    NULLIF(check_in_location, ''),
    NULLIF(check_out_location, ''),
    NULLIF(status, ''),
    NULLIF(NULLIF(sync_timestamp, ''), '###########')::timestamp,
    NULLIF(check_in_address, ''),
    NULLIF(check_out_address, ''),
    NULLIF(check_in_latitude, '')::double precision,
    NULLIF(check_in_longitude, '')::double precision,
    NULLIF(check_out_latitude, '')::double precision,
    NULLIF(check_out_longitude, '')::double precision
FROM attendance_import_stage;

-- Verify the inserted count before committing. Expected: 1,365.
DO $$ BEGIN IF (SELECT COUNT(*) FROM public.attendance) <> 1365 THEN RAISE EXCEPTION 'Import count mismatch; transaction will roll back.'; END IF; END $$;
COMMIT;

-- Note: Name is preserved in staging only because public.attendance has no name column.
-- Sync Timestamp values that were literally ########### in the TXT are imported as NULL.